/**
 * In-memory location search over a NormalizedNavGraph.
 *
 * Performs case-insensitive prefix matching on node label, room number,
 * description, and building name. Results are grouped by building → floor
 * and only include buildings/floors that have at least one matching node.
 *
 * Performance: the search index is built lazily in useMemo, keyed on graph.
 */

import { useMemo } from 'react';
import type { NormalizedNavGraph } from '../domain/navGraph';
import type { NavNode, NavNodeType } from '../../src/shared/types';

/* ──────────────── Result types ──────────────── */

/** A node matched by search, enriched with building/floor context. */
export interface SearchNode {
  node: NavNode;
  buildingId: number;
  buildingName: string;
  floorId: number;
  floorNumber: number;
}

/** A floor that contains at least one matching SearchNode. */
export interface SearchFloor {
  floorId: number;
  floorNumber: number;
  nodes: SearchNode[];
}

/** A building that contains at least one matching SearchNode. */
export interface SearchBuilding {
  buildingId: number;
  buildingName: string;
  floors: SearchFloor[];
}

/** Return type of the useLocationSearch hook. */
export interface UseLocationSearchResult {
  buildings: SearchBuilding[];
  /** Total number of matching nodes across all buildings. */
  totalMatches: number;
}

/* ──────────────── Search helpers ──────────────── */

/**
 * Returns true if query is a case-insensitive prefix of any searchTarget.
 * Empty query always matches.
 */
function isPrefixMatch(query: string, searchTarget: string): boolean {
  if (query.length === 0) return true;
  return searchTarget.toLowerCase().startsWith(query.toLowerCase());
}

/**
 * Returns true if query matches any searchable field of a node.
 */
function nodeMatchesQuery(
  query: string,
  node: NavNode,
  buildingName: string,
): boolean {
  if (!isPrefixMatch(query, node.label)) return false;
  if (node.roomNumber && isPrefixMatch(query, node.roomNumber)) return true;
  if (node.description && isPrefixMatch(query, node.description)) return true;
  if (isPrefixMatch(query, buildingName)) return true;
  return false;
}

/* ──────────────── Hook ───────────────── */

/**
 * In-memory search over a NormalizedNavGraph.
 *
 * @param graph - The normalized navigation graph to search
 * @param query - Search string (prefix match on label, roomNumber, description, buildingName)
 * @param typeFilter - Optional set of NavNodeTypes to restrict results (e.g. only 'room')
 */
export function useLocationSearch(
  graph: NormalizedNavGraph,
  query: string,
  typeFilter?: Set<NavNodeType>,
): UseLocationSearchResult {
  return useMemo(() => {
    const trimmed = query.trim();
    const buildings: SearchBuilding[] = [];
    let totalMatches = 0;

    for (const building of graph.graph.buildings) {
      const matchedFloors: SearchFloor[] = [];

      for (const floor of building.floors) {
        const floorRecord = graph.floorById.get(floor.id);
        const floorNumber = floorRecord?.floorNumber ?? floor.floorNumber;

        const matchedNodes: SearchNode[] = [];

        for (const node of floor.nodes) {
          // Skip non-searchable nodes
          if (!node.searchable) continue;

          // Apply type filter if provided
          if (typeFilter && !typeFilter.has(node.type)) continue;

          // Apply query filter if provided
          if (trimmed.length > 0 && !nodeMatchesQuery(trimmed, node, building.name)) {
            continue;
          }

          matchedNodes.push({
            node,
            buildingId: building.id,
            buildingName: building.name,
            floorId: floor.id,
            floorNumber,
          });
        }

        // Only include floors with matching nodes
        if (matchedNodes.length > 0) {
          // Sort nodes by label
          matchedNodes.sort((a, b) => a.node.label.localeCompare(b.node.label));

          matchedFloors.push({
            floorId: floor.id,
            floorNumber,
            nodes: matchedNodes,
          });

          totalMatches += matchedNodes.length;
        }
      }

      // Only include buildings with matching floors
      if (matchedFloors.length > 0) {
        // Sort floors by floor number ascending
        matchedFloors.sort((a, b) => a.floorNumber - b.floorNumber);

        buildings.push({
          buildingId: building.id,
          buildingName: building.name,
          floors: matchedFloors,
        });
      }
    }

    // Sort buildings by name
    buildings.sort((a, b) => a.buildingName.localeCompare(b.buildingName));

    return { buildings, totalMatches };
  }, [graph, query, typeFilter]);
}

/**
 * Tests for useLocationSearch hook.
 *
 * Covers:
 * - empty query returns all searchable nodes grouped by building/floor
 * - prefix matching on node label
 * - prefix matching on room number
 * - prefix matching on description
 * - prefix matching on building name
 * - type filter excludes non-matching node types
 * - empty result for nonsense query
 * - result count matches
 * - sorting: buildings by name, floors by number, nodes by label
 */

import { renderHook } from '@testing-library/react';
import { useLocationSearch } from './useLocationSearch';
import { normalizeNavGraph } from '../domain/navGraph';
import type { NavBuilding, NavFloor, NavGraph } from '../../src/shared/types';

/* ──────────────── Test graph factory ──────────────── */

/**
 * Creates a test graph with:
