    { id: 'lib-f2-e3', sourceId: 'lib-f2-cafeteria', targetId: 'lib-f2-study-c', standardWeight: 0.2, accessibleWeight: 0.2, accessible: true, bidirectional: true },
    { id: 'lib-f2-e4', sourceId: 'lib-f2-cafeteria', targetId: 'lib-f2-restroom', standardWeight: 0.2, accessibleWeight: 0.2, accessible: true, bidirectional: true },
  ];

  // Floor 3 of Library
  const libF3Nodes = [
    { id: 'lib-f3-stairs', x: 0.9, y: 0.5, floorId: 3, type: 'stairs' as const, searchable: false, label: 'Stairs', connectsToNodeBelowId: 'lib-f2-stairs', connectsToFloorBelowId: 2 },
    { id: 'lib-f3-elevator', x: 0.1, y: 0.5, floorId: 3, type: 'elevator' as const, searchable: true, label: 'Elevator', description: 'Wheelchair accessible' },
    { id: 'lib-f3-rare-books', x: 0.5, y: 0.5, floorId: 3, type: 'room' as const, searchable: true, label: 'Rare Books Collection', roomNumber: '301', description: 'Special collections' },
    { id: 'lib-f3-archives', x: 0.3, y: 0.6, floorId: 3, type: 'room' as const, searchable: true, label: 'Archives', roomNumber: '302', description: 'Historical documents' },
  ];

  const libF3Edges = [
    { id: 'lib-f3-e1', sourceId: 'lib-f3-stairs', targetId: 'lib-f3-elevator', standardWeight: 0.4, accessibleWeight: 0.4, accessible: true, bidirectional: true },
    { id: 'lib-f3-e2', sourceId: 'lib-f3-elevator', targetId: 'lib-f3-rare-books', standardWeight: 0.3, accessibleWeight: 0.3, accessible: true, bidirectional: true },
    { id: 'lib-f3-e3', sourceId: 'lib-f3-rare-books', targetId: 'lib-f3-archives', standardWeight: 0.2, accessibleWeight: 0.2, accessible: true, bidirectional: true },
  ];

  // Science Building Floor 1
  const sciF1Nodes = [
    { id: 'sci-f1-entrance', x: 0.5, y: 0.9, floorId: 4, type: 'entrance' as const, searchable: true, label: 'Science Building Entrance', roomNumber: undefined, description: 'Main entrance' },
    { id: 'sci-f1-lab-101', x: 0.3, y: 0.5, floorId: 4, type: 'room' as const, searchable: true, label: 'Chemistry Lab', roomNumber: '101', description: 'Teaching chemistry lab' },
