  // Science Building Floor 2
  const sciF2Nodes = [
    { id: 'sci-f2-stairs', x: 0.9, y: 0.5, floorId: 5, type: 'stairs' as const, searchable: false, label: 'Stairs', connectsToNodeBelowId: 'sci-f1-stairs', connectsToFloorBelowId: 4 },
