  const sciF2Edges = [
    { id: 'sci-f2-e1', sourceId: 'sci-f2-stairs', targetId: 'sci-f2-lab-201', standardWeight: 0.3, accessibleWeight: 0.3, accessible: true, bidirectional: true },
