  const sciFloor1: NavFloor = { id: 4, floorNumber: 1, imagePath: '/sci-f1.png', updatedAt: '2024-01-01T00:00:00Z', nodes: sciF1Nodes, edges: sciF1Edges };
  const sciFloor2: NavFloor = { id: 5, floorNumber: 2, imagePath: '/sci-f2.png', updatedAt: '2024-01-01T00:00:00Z', nodes: sciF2Nodes, edges: sciF2Edges };
  const sciFloor3: NavFloor = { id: 6, floorNumber: 3, imagePath: '/sci-f3.png', updatedAt: '2024-01-01T00:00:00Z', nodes: sciF3Nodes, edges: sciF3Edges };

  const library: NavBuilding = { id: 1, name: 'Library', floors: [libFloor1, libFloor2, libFloor3] };
  const science: NavBuilding = { id: 2, name: 'Science Building', floors: [sciFloor1, sciFloor2, sciFloor3] };

  return { buildings: [library, science] };
}

function normalizeGraph(): ReturnType<typeof normalizeNavGraph>['data'] {
  const result = normalizeNavGraph(createTestNavGraph());
  if (!result.ok) {
    throw new Error('Failed to normalize test nav graph: ' + result.error.message);
  }
  return result.data;
}

/* ──────────────── Tests ──────────────── */

describe('useLocationSearch', () => {
  describe('empty query', () => {
    it('returns all searchable nodes grouped by building/floor', () => {
      const graph = normalizeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));

      expect(result.current.buildings).toHaveLength(2);
      expect(result.current.buildings[0]?.buildingName).toBe('Library');
      expect(result.current.buildings[1]?.buildingName).toBe('Science Building');

      // Library has 3 floors with searchable nodes (stairs excluded)
      const libBuilding = result.current.buildings.find(b => b.buildingName === 'Library');
      expect(libBuilding?.floors).toHaveLength(3);
    });

    it('totalMatches counts only searchable nodes', () => {
      const graph = normalizeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));

      // Count all searchable nodes manually:
      // Library F1: entrance, reception, study-a, study-b, elevator = 5
      // Library F2: elevator, cafeteria, study-c, restroom = 4
      // Library F3: elevator, rare-books, archives = 3
      // Science F1: entrance, lab-101, lab-102, restroom = 4
      // Science F2: lab-201, study = 2
      // Science F3: lab-301 = 1
      // Total: 19
      expect(result.current.totalMatches).toBe(19);
    });

    it('buildings are sorted alphabetically', () => {
      const graph = normalizeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));

      const buildingNames = result.current.buildings.map(b => b.buildingName);
      expect(buildingNames).toEqual(['Library', 'Science Building']);
    });

    it('floors within each building are sorted by floor number', () => {
      const graph = normalizeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));

      const libFloors = result.current.buildings.find(b => b.buildingName === 'Library')?.floors;
      const floorNumbers = libFloors?.map(f => f.floorNumber);
      expect(floorNumbers).toEqual([1, 2, 3]);
    });

    it('nodes within each floor are sorted by label', () => {
      const graph = normalizeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, ''));

      const libF1Nodes = result.current.buildings
        .find(b => b.buildingName === 'Library')
        ?.floors.find(f => f.floorNumber === 1)
        ?.nodes.map(n => n.node.label);

      // Labels: "Cafeteria" excluded (F2), elevator comes after entrance before room labels
      // F1 labels: "Elevator", "Main Entrance", "Reception", "Study Room A", "Study Room B"
      expect(libF1Nodes).toEqual(['Elevator', 'Main Entrance', 'Reception', 'Study Room A', 'Study Room B']);
    });
  });

  describe('prefix matching on label', () => {
    it('matches node label prefix "Study"', () => {
      const graph = normalizeGraph();
      const { result } = renderHook(() => useLocationSearch(graph, 'Study'));

      expect(result.current.totalMatches).toBeGreaterThan(0);
      result.current.buildings.forEach(building => {
        building.floors.forEach(floor => {
          floor.nodes.forEach(searchNode => {
            expect(searchNode.node.label.toLowerCase()).toMatch(/^study/);
          });
        });
      });
    });

    it('matching is case-insensitive', () => {
      const graph = normalizeGraph();
